    def _reject_constant(value: str) -> None:
        raise ValueError(f"invalid JSON constant {value}")

    def _write(self, entries: dict[str, dict[str, Any]]) -> None:
        parent = self.path.parent
        try:
            parent.mkdir(parents=True, exist_ok=True)
